<script setup lang="ts">defineProps<{label:string;modelValue:string;options:string[];placeholder?:string}>();defineEmits<{ 'update:modelValue':[value:string] }>();</script>
<template><label>{{label}}<select :value="modelValue" @change="$emit('update:modelValue',($event.target as HTMLSelectElement).value)"><option value="">{{placeholder||'请选择'}}</option><option v-for="option in options" :key="option" :value="option">{{option}}</option></select></label></template>
